CREATE TABLE "notification_event" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE cascade, "branchId" text REFERENCES "branch"("id") ON DELETE cascade, "type" text NOT NULL, "severity" text NOT NULL, "entityType" text NOT NULL, "entityId" text, "dedupeKey" text NOT NULL, "payload" json NOT NULL DEFAULT '{}'::json, "materializedAt" timestamp, "createdAt" timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "notification_event_org_dedupe_unique" ON "notification_event" ("organizationId","dedupeKey");
CREATE INDEX "notification_event_org_created_idx" ON "notification_event" ("organizationId","createdAt");
CREATE TABLE "notification_delivery" ("id" text PRIMARY KEY NOT NULL, "eventId" text NOT NULL REFERENCES "notification_event"("id") ON DELETE cascade, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE cascade, "userId" text REFERENCES "user"("id") ON DELETE set null, "recipientEmail" text NOT NULL, "recipientName" text, "status" text NOT NULL DEFAULT 'PENDING', "attempts" integer NOT NULL DEFAULT 0, "leaseUntil" timestamp, "nextRetryAt" timestamp, "providerMessageId" text, "lastError" text, "sentAt" timestamp, "failedAt" timestamp, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "notification_delivery_event_recipient_unique" ON "notification_delivery" ("eventId","recipientEmail");
CREATE INDEX "notification_delivery_due_idx" ON "notification_delivery" ("status","nextRetryAt");
CREATE INDEX "notification_delivery_lease_idx" ON "notification_delivery" ("status","leaseUntil");
CREATE TABLE "notification_preference" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE cascade, "branchId" text REFERENCES "branch"("id") ON DELETE cascade, "role" text NOT NULL, "type" text NOT NULL, "enabled" boolean NOT NULL DEFAULT true, "digestTime" text NOT NULL DEFAULT '20:00', "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "notification_preference_org_scope_unique" ON "notification_preference" ("organizationId","role","type") WHERE "branchId" IS NULL;
CREATE UNIQUE INDEX "notification_preference_branch_scope_unique" ON "notification_preference" ("organizationId","branchId","role","type") WHERE "branchId" IS NOT NULL;
CREATE TABLE "notification_alert_state" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE cascade, "branchId" text NOT NULL REFERENCES "branch"("id") ON DELETE cascade, "productId" text NOT NULL REFERENCES "product"("id") ON DELETE cascade, "lowStockActive" boolean NOT NULL DEFAULT false, "outOfStockActive" boolean NOT NULL DEFAULT false, "lowStockEpisode" integer NOT NULL DEFAULT 0, "outOfStockEpisode" integer NOT NULL DEFAULT 0, "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "notification_alert_state_product_branch_unique" ON "notification_alert_state" ("productId","branchId");
CREATE INDEX "notification_alert_state_org_branch_idx" ON "notification_alert_state" ("organizationId","branchId");
